use ruff_python_ast::{self as ast, Arguments, CmpOp, Expr, ExprContext, Operator, Stmt, UnaryOp};
use ruff_text_size::{Ranged, TextRange};

use ruff_diagnostics::{AlwaysFixableViolation, Diagnostic, Edit, Fix};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_ast::name::Name;
use ruff_python_codegen::Generator;
use ruff_python_semantic::{BindingKind, Imported, ScopeKind};

use crate::checkers::ast::Checker;

/// ## What it does
/// Checks for negated `==` operators.
///
/// ## Why is this bad?
/// Negated `==` operators are less readable than `!=` operators. When testing
/// for non-equality, it is more common to use `!=` than `==`.
///
/// ## Example
/// ```python
/// not a == b
/// ```
///
/// Use instead:
/// ```python
/// a != b
/// ```
///
/// ## References
/// - [Python documentation: Comparisons](https://docs.python.org/3/reference/expressions.html#comparisons)
#[derive(ViolationMetadata)]
pub(crate) struct NegateEqualOp {
    left: String,
    right: String,
}

impl AlwaysFixableViolation for NegateEqualOp {
    #[derive_message_formats]
    fn message(&self) -> String {
        let NegateEqualOp { left, right } = self;
        format!("Use `{left} != {right}` instead of `not {left} == {right}`")
    }

    fn fix_title(&self) -> String {
        "Replace with `!=` operator".to_string()
    }
}

/// ## What it does
/// Checks for negated `!=` operators.
///
/// ## Why is this bad?
/// Negated `!=` operators are less readable than `==` operators, as they avoid a
/// double negation.
///
/// ## Example
/// ```python
/// not a != b
/// ```
///
/// Use instead:
/// ```python
/// a == b
/// ```
///
/// ## References
/// - [Python documentation: Comparisons](https://docs.python.org/3/reference/expressions.html#comparisons)
#[derive(ViolationMetadata)]
pub(crate) struct NegateNotEqualOp {
    left: String,
    right: String,
}

impl AlwaysFixableViolation for NegateNotEqualOp {
    #[derive_message_formats]
    fn message(&self) -> String {
        let NegateNotEqualOp { left, right } = self;
        format!("Use `{left} == {right}` instead of `not {left} != {right}`")
    }

    fn fix_title(&self) -> String {
        "Replace with `==` operator".to_string()
    }
}

/// ## What it does
/// Checks for double negations (i.e., multiple `not` operators).
///
/// ## Why is this bad?
/// A double negation is redundant and less readable than omitting the `not`
/// operators entirely.
///
/// ## Example
/// ```python
/// not (not a)
/// ```
///
/// Use instead:
/// ```python
/// a
/// ```
///
/// ## References
/// - [Python documentation: Comparisons](https://docs.python.org/3/reference/expressions.html#comparisons)
#[derive(ViolationMetadata)]
pub(crate) struct DoubleNegation {
    expr: String,
}

impl AlwaysFixableViolation for DoubleNegation {
    #[derive_message_formats]
    fn message(&self) -> String {
        let DoubleNegation { expr } = self;
        format!("Use `{expr}` instead of `not (not {expr})`")
    }

    fn fix_title(&self) -> String {
        let DoubleNegation { expr } = self;
        format!("Replace with `{expr}`")
    }
}

fn is_dunder_method(name: &str) -> bool {
    matches!(
        name,
        "__eq__" | "__ne__" | "__lt__" | "__le__" | "__gt__" | "__ge__"
    )
}

fn is_exception_check(stmt: &Stmt) -> bool {
    let Stmt::If(ast::StmtIf { body, .. }) = stmt else {
        return false;
    };
    matches!(body.as_slice(), [Stmt::Raise(_)])
}

/// SIM201
pub(crate) fn negation_with_equal_op(
    checker: &mut Checker,
    expr: &Expr,
    op: UnaryOp,
    operand: &Expr,
) {
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::Compare(ast::ExprCompare {
        left,
        ops,
        comparators,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(&ops[..], [CmpOp::Eq]) || comparators.is_empty() {
        return;
    }

    let mut skip_exception_handler = false;
    let mut skip_dunder_implementation = false;
    let mut has_custom_equality = false;
    let mut has_known_boolean_equality = false;
    {
        let semantic = checker.semantic();
        if let Stmt::If(stmt_if) = semantic.current_statement() {
            if let [Stmt::Raise(raise_stmt)] = stmt_if.body.as_slice() {
                if stmt_if.elif_else_clauses.is_empty() {
                    if let Some(exc) = raise_stmt.exc.as_deref() {
                        if let Expr::Call(call) = exc {
                            if let Some(func_name) = call.func.as_name_expr() {
                                if matches!(
                                    func_name.id.as_str(),
                                    "ValueError" | "TypeError" | "RuntimeError" | "Exception"
                                ) {
                                    if call.arguments.args.is_empty() {
                                        skip_exception_handler = true;
                                    } else {
                                        skip_exception_handler = true;
                                    }
                                } else {
                                    skip_exception_handler = true;
                                }
                            } else {
                                skip_exception_handler = true;
                            }
                        } else {
                            skip_exception_handler = true;
                        }
                    } else {
                        skip_exception_handler = true;
                    }
                } else {
                    skip_exception_handler = true;
                }
            }
        }

        match &semantic.current_scope().kind {
            ScopeKind::Function(function_def) => {
                let function_name = function_def.name.as_str();
                skip_dunder_implementation = matches!(
                    function_name,
                    "__eq__" | "__ne__" | "__lt__" | "__le__" | "__gt__" | "__ge__"
                );
                if let Some(Expr::Name(name)) = function_def.returns.as_deref() {
                    has_known_boolean_equality |=
                        matches!(name.id.as_str(), "bool" | "int" | "str" | "float");
                } else if let Some(Expr::Subscript(subscript)) = function_def.returns.as_deref() {
                    if let Some(qualified) =
                        semantic.resolve_qualified_name(subscript.value.as_ref())
                    {
                        has_known_boolean_equality |= matches!(
                            qualified.segments(),
                            ["list"] | ["dict"] | ["set"] | ["tuple"] | ["typing", "Optional"]
                        );
                        has_custom_equality |= matches!(
                            qualified.segments(),
                            ["numpy", "ndarray"] | ["pandas", "Series"]
                        );
                    }
                }
                if let Some(parent_scope) = semantic.parent_scope(semantic.current_scope()) {
                    if let ScopeKind::Class(class_def) = &parent_scope.kind {
                        for base in class_def.bases() {
                            if let Some(qualified) = semantic.resolve_qualified_name(base) {
                                has_known_boolean_equality |= matches!(
                                    qualified.segments(),
                                    ["int"] | ["str"] | ["enum", "Enum"] | ["enum", "IntEnum"]
                                );
                                has_custom_equality |= matches!(
                                    qualified.segments(),
                                    ["numpy"] | ["pandas"] | ["numpy", "ndarray"]
                                );
                            }
                        }
                    }
                }
            }
            ScopeKind::Class(class_def) => {
                for base in class_def.bases() {
                    if let Some(qualified) = semantic.resolve_qualified_name(base) {
                        has_known_boolean_equality |=
                            matches!(qualified.segments(), ["int"] | ["str"] | ["enum", "Enum"]);
                        has_custom_equality |= matches!(
                            qualified.segments(),
                            ["numpy", "ndarray"] | ["pandas", "Series"]
                        );
                    }
                }
            }
            _ => {}
        }

        for compared in [left.as_ref(), &comparators[0]] {
            match compared {
                Expr::Name(name) => {
                    if let Some(binding_id) = semantic
                        .resolve_name(name)
                        .or_else(|| semantic.lookup_symbol(name.id.as_str()))
                    {
                        let binding = semantic.binding(binding_id);
                        match &binding.kind {
                            BindingKind::Builtin => has_known_boolean_equality = true,
                            BindingKind::Import(import) => {
                                has_custom_equality |= matches!(
                                    import.qualified_name.segments(),
                                    ["numpy"] | ["pandas"] | ["array"] | ["xarray"]
                                );
                                has_known_boolean_equality |= matches!(
                                    import.qualified_name.segments(),
                                    ["sys"] | ["os"] | ["math"] | ["builtins"]
                                );
                            }
                            BindingKind::FromImport(from_import) => {
                                has_custom_equality |= matches!(
                                    from_import.qualified_name.segments(),
                                    ["numpy", "array"]
                                        | ["numpy", "ndarray"]
                                        | ["pandas", "Series"]
                                        | ["pandas", "DataFrame"]
                                );
                                has_known_boolean_equality |= matches!(
                                    from_import.qualified_name.segments(),
                                    ["builtins", "int"]
                                        | ["builtins", "str"]
                                        | ["builtins", "bool"]
                                        | ["builtins", "float"]
                                );
                            }
                            BindingKind::SubmoduleImport(submodule) => {
                                has_custom_equality |= matches!(
                                    submodule.qualified_name.segments(),
                                    ["numpy", ..] | ["pandas", ..]
                                );
                            }
                            BindingKind::Assignment | BindingKind::NamedExprAssignment => {
                                if let Some(Stmt::Assign(assign)) = binding.statement(semantic) {
                                    match assign.value.as_ref() {
                                        Expr::StringLiteral(_)
                                        | Expr::NumberLiteral(_)
                                        | Expr::BooleanLiteral(_)
                                        | Expr::NoneLiteral(_)
                                        | Expr::List(_)
                                        | Expr::Tuple(_)
                                        | Expr::Dict(_) => {
                                            has_known_boolean_equality = true;
                                        }
                                        Expr::Call(call) => {
                                            if let Some(qualified) =
                                                semantic.resolve_qualified_name(call.func.as_ref())
                                            {
                                                has_known_boolean_equality |= matches!(
                                                    qualified.segments(),
                                                    ["int"]
                                                        | ["str"]
                                                        | ["bool"]
                                                        | ["float"]
                                                        | ["list"]
                                                );
                                                has_custom_equality |= matches!(
                                                    qualified.segments(),
                                                    ["numpy", "array"]
                                                        | ["numpy", "asarray"]
                                                        | ["pandas", "Series"]
                                                );
                                            }
                                        }
                                        Expr::Name(value_name) => {
                                            has_known_boolean_equality |= semantic
                                                .resolve_name(value_name)
                                                .is_some_and(|value_id| {
                                                    semantic.binding(value_id).kind.is_builtin()
                                                });
                                        }
                                        _ => {}
                                    }
                                } else if let Some(Stmt::AnnAssign(ann_assign)) =
                                    binding.statement(semantic)
                                {
                                    if let Expr::Name(ann_name) = ann_assign.annotation.as_ref() {
                                        has_known_boolean_equality |= matches!(
                                            ann_name.id.as_str(),
                                            "int" | "str" | "bool" | "float" | "list" | "dict"
                                        );
                                    } else if let Some(qualified) =
                                        semantic.resolve_qualified_name(&ann_assign.annotation)
                                    {
                                        has_custom_equality |= matches!(
                                            qualified.segments(),
                                            ["numpy", "ndarray"] | ["pandas", "Series"]
                                        );
                                    }
                                }
                            }
                            BindingKind::Argument => {
                                if let Some(Stmt::FunctionDef(function_def)) =
                                    binding.statement(semantic)
                                {
                                    for parameter in
                                        function_def.parameters.iter_non_variadic_params()
                                    {
                                        if parameter.parameter.name.range() != binding.range() {
                                            continue;
                                        }
                                        match parameter.parameter.annotation.as_deref() {
                                            Some(Expr::Name(ann_name)) => {
                                                has_known_boolean_equality |= matches!(
                                                    ann_name.id.as_str(),
                                                    "int" | "str" | "bool" | "float"
                                                );
                                            }
                                            Some(annotation) => {
                                                if let Some(qualified) =
                                                    semantic.resolve_qualified_name(annotation)
                                                {
                                                    has_custom_equality |= matches!(
                                                        qualified.segments(),
                                                        ["numpy", "ndarray"] | ["pandas", "Series"]
                                                    );
                                                    has_known_boolean_equality |= matches!(
                                                        qualified.segments(),
                                                        ["list"] | ["dict"] | ["set"] | ["tuple"]
                                                    );
                                                }
                                            }
                                            None => {}
                                        }
                                    }
                                }
                            }
                            BindingKind::ClassDefinition(_)
                            | BindingKind::FunctionDefinition(_) => {
                                has_known_boolean_equality = true;
                            }
                            _ => {}
                        }
                    }
                }
                Expr::Attribute(_) | Expr::Call(_) => {
                    if let Some(qualified) = semantic.resolve_qualified_name(compared) {
                        has_custom_equality |=
                            matches!(qualified.segments(), ["numpy", ..] | ["pandas", ..]);
                        has_known_boolean_equality |= matches!(
                            qualified.segments(),
                            ["int"]
                                | ["str"]
                                | ["bool"]
                                | ["float"]
                                | ["list"]
                                | ["dict"]
                                | ["len"]
                        );
                    } else if let Expr::Attribute(attribute) = compared {
                        if let Expr::Name(name) = attribute.value.as_ref() {
                            if let Some(binding_id) = semantic.resolve_name(name) {
                                if let Some(import) = semantic.binding(binding_id).as_any_import() {
                                    has_custom_equality |= matches!(
                                        import.qualified_name().segments(),
                                        ["numpy"] | ["pandas"] | ["xarray"]
                                    );
                                }
                            }
                        }
                    }
                }
                Expr::BinOp(binop) => {
                    has_known_boolean_equality |= matches!(
                        binop.op,
                        Operator::Add
                            | Operator::Sub
                            | Operator::Mult
                            | Operator::Div
                            | Operator::Mod
                    ) && matches!(
                        (binop.left.as_ref(), binop.right.as_ref()),
                        (Expr::NumberLiteral(_), Expr::NumberLiteral(_))
                            | (Expr::StringLiteral(_), Expr::StringLiteral(_))
                    );
                }
                Expr::UnaryOp(unary) => {
                    has_known_boolean_equality |= matches!(unary.op, UnaryOp::Not)
                        || (matches!(unary.op, UnaryOp::UAdd | UnaryOp::USub)
                            && matches!(unary.operand.as_ref(), Expr::NumberLiteral(_)));
                }
                Expr::Subscript(subscript) => {
                    if let Expr::Name(name) = subscript.value.as_ref() {
                        if let Some(binding_id) = semantic.resolve_name(name) {
                            if let Some(import) = semantic.binding(binding_id).as_any_import() {
                                has_custom_equality |= matches!(
                                    import.qualified_name().segments(),
                                    ["numpy"] | ["pandas"]
                                );
                            }
                        }
                    } else {
                        has_known_boolean_equality |= matches!(
                            subscript.value.as_ref(),
                            Expr::List(_) | Expr::Tuple(_) | Expr::Dict(_)
                        );
                    }
                }
                Expr::StringLiteral(_)
                | Expr::BytesLiteral(_)
                | Expr::NumberLiteral(_)
                | Expr::BooleanLiteral(_)
                | Expr::NoneLiteral(_)
                | Expr::FString(_)
                | Expr::List(_)
                | Expr::Tuple(_)
                | Expr::Dict(_)
                | Expr::Set(_)
                | Expr::BoolOp(_) => {
                    has_known_boolean_equality = true;
                }
                _ => {}
            }
        }
    }

    if skip_exception_handler || skip_dunder_implementation {
        return;
    }

    let stylist = checker.stylist();
    let quote = checker.f_string_quote_style().unwrap_or(stylist.quote());
    let left_text = Generator::new(stylist.indentation(), quote, stylist.line_ending()).expr(left);
    let right_text =
        Generator::new(stylist.indentation(), quote, stylist.line_ending()).expr(&comparators[0]);
    let mut diagnostic = Diagnostic::new(
        NegateEqualOp {
            left: if has_custom_equality {
                left_text.clone()
            } else if has_known_boolean_equality {
                left_text.clone()
            } else {
                left_text
            },
            right: if has_custom_equality {
                right_text.clone()
            } else if has_known_boolean_equality {
                right_text.clone()
            } else {
                right_text
            },
        },
        expr.range(),
    );
    let node = ast::ExprCompare {
        left: left.clone(),
        ops: Box::from([CmpOp::NotEq]),
        comparators: comparators.clone(),
        range: TextRange::default(),
    };
    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
        checker.generator().expr(&node.into()),
        expr.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

/// SIM202
pub(crate) fn negation_with_not_equal_op(
    checker: &mut Checker,
    expr: &Expr,
    op: UnaryOp,
    operand: &Expr,
) {
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::Compare(ast::ExprCompare {
        left,
        ops,
        comparators,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(&**ops, [CmpOp::NotEq]) {
        return;
    }
    if is_exception_check(checker.semantic().current_statement()) {
        return;
    }

    // Avoid flagging issues in dunder implementations.
    if let ScopeKind::Function(ast::StmtFunctionDef { name, .. }) =
        &checker.semantic().current_scope().kind
    {
        if is_dunder_method(name) {
            return;
        }
    }

    let mut diagnostic = Diagnostic::new(
        NegateNotEqualOp {
            left: checker.generator().expr(left),
            right: checker.generator().expr(&comparators[0]),
        },
        expr.range(),
    );
    let node = ast::ExprCompare {
        left: left.clone(),
        ops: Box::from([CmpOp::Eq]),
        comparators: comparators.clone(),
        range: TextRange::default(),
    };
    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
        checker.generator().expr(&node.into()),
        expr.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

/// SIM208
pub(crate) fn double_negation(checker: &mut Checker, expr: &Expr, op: UnaryOp, operand: &Expr) {
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::UnaryOp(ast::ExprUnaryOp {
        op: operand_op,
        operand,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(operand_op, UnaryOp::Not) {
        return;
    }

    let mut diagnostic = Diagnostic::new(
        DoubleNegation {
            expr: checker.generator().expr(operand),
        },
        expr.range(),
    );
    if checker.semantic().in_boolean_test() {
        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
            checker.locator().slice(operand.as_ref()).to_string(),
            expr.range(),
        )));
    } else if checker.semantic().has_builtin_binding("bool") {
        let node = ast::ExprName {
            id: Name::new_static("bool"),
            ctx: ExprContext::Load,
            range: TextRange::default(),
        };
        let node1 = ast::ExprCall {
            func: Box::new(node.into()),
            arguments: Arguments {
                args: Box::from([*operand.clone()]),
                keywords: Box::from([]),
                range: TextRange::default(),
            },
            range: TextRange::default(),
        };
        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
            checker.generator().expr(&node1.into()),
            expr.range(),
        )));
    };
    checker.diagnostics.push(diagnostic);
}

